"""LaTeX emission shared by the generated artefacts.

Everything written here is machine-generated and re-runnable; nothing in
`thesis/generated/` is ever hand-edited (CLAUDE.md, "thesis/ -- the manuscript").

The ELTE FI class (`elteikthesis.cls`) loads `longtable`, `array`, `makecell`
and `multirow` but NOT `booktabs`, so every generated table opens with
`\\providecommand` fallbacks for the three booktabs rules: the file compiles
against the stock template, and picks up real booktabs rules the moment the
author adds `\\usepackage{booktabs}`.
"""

HEADER = (
    "% GENERATED by `{command}` -- do not edit.\n"
    "% Source of truth: {source}\n"
)

# `\providecommand` is a no-op when booktabs is loaded, so the real rules win
# whenever they exist. `\hline` is the degraded but valid fallback.
BOOKTABS_FALLBACK = (
    "\\providecommand{\\toprule}{\\hline}\n"
    "\\providecommand{\\midrule}{\\hline}\n"
    "\\providecommand{\\bottomrule}{\\hline}\n"
)

_ESCAPES = {
    "\\": "\\textbackslash{}",
    "{": "\\{",
    "}": "\\}",
    "&": "\\&",
    "%": "\\%",
    "$": "\\$",
    "#": "\\#",
    "_": "\\_",
    "~": "\\textasciitilde{}",
    "^": "\\textasciicircum{}",
}

# Substituting one character at a time would re-escape the braces that
# `\textbackslash{}` and friends introduce, so the input is walked once.
_TRANSLATION = str.maketrans(_ESCAPES)


def escape(text):
    """Escape the ten TeX special characters in arbitrary manifest text."""
    if text is None:
        return ""
    return str(text).translate(_TRANSLATION)


def oneline(text, limit=None):
    """Collapse whitespace; the manifest folds long descriptions over lines."""
    collapsed = " ".join(str(text or "").split())
    if limit is not None and len(collapsed) > limit:
        # U+2026 would need inputenc handling in a pdfLaTeX build; "..." does not.
        collapsed = collapsed[: limit - 3].rstrip() + "..."
    return collapsed


def cell(text, limit=None):
    return escape(oneline(text, limit))


def header(command, source):
    return HEADER.format(command=command, source=source)


def row(cells):
    return " & ".join(cells) + " \\\\"


def longtable(columns, head, body, caption, label, footer=None):
    """A `longtable` with a repeated header and a generated provenance footer.

    A longtable is not a float, so the caption goes in the first head and
    `\\endfirsthead` / `\\endhead` carry it across the page break.
    """
    lines = [
        f"\\begin{{longtable}}{{{columns}}}",
        f"\\caption{{{caption}}}\\label{{{label}}}\\\\",
        "\\toprule",
        row(head),
        "\\midrule",
        "\\endfirsthead",
        "\\multicolumn{%d}{l}{\\footnotesize\\itshape continued from the previous page}\\\\"
        % len(head),
        "\\toprule",
        row(head),
        "\\midrule",
        "\\endhead",
        "\\midrule",
        "\\multicolumn{%d}{r}{\\footnotesize\\itshape continued on the next page}\\\\"
        % len(head),
        "\\endfoot",
        "\\bottomrule",
        "\\endlastfoot",
    ]
    lines += body
    if footer:
        lines.append("\\midrule")
        lines.append(
            "\\multicolumn{%d}{@{}p{\\dimexpr\\linewidth-2\\tabcolsep\\relax}@{}}"
            "{\\footnotesize %s}\\\\" % (len(head), footer)
        )
    lines.append("\\end{longtable}")
    return "\n".join(lines) + "\n"


def table(columns, head, body, caption, label, footer=None, placement="H"):
    """A `table` float around a plain `tabular`, for the short result tables."""
    lines = [
        f"\\begin{{table}}[{placement}]",
        "\\centering",
        "\\footnotesize",
        f"\\begin{{tabular}}{{{columns}}}",
        "\\toprule",
        row(head),
        "\\midrule",
    ]
    lines += body
    lines.append("\\bottomrule")
    if footer:
        lines.append(
            "\\multicolumn{%d}{@{}p{\\dimexpr\\linewidth-2\\tabcolsep\\relax}@{}}"
            "{\\footnotesize %s}\\\\" % (len(head), footer)
        )
    lines.append("\\end{tabular}")
    lines.append(f"\\caption{{{caption}}}")
    lines.append(f"\\label{{{label}}}")
    lines.append("\\end{table}")
    return "\n".join(lines) + "\n"
